{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Ketoconazole, the closest structural analogue sharing the dichlorophenyl-substituted cyclic ether, piperazine-phenyl ether, and azole motifs, has a mean oral bioavailability of approximately 75% in healthy volunteers, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fluconazole, a triazole antifungal, has an absolute oral bioavailability of 94% in healthy volunteers, supporting high oral bioavailability for this azole-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Voriconazole, a triazole antifungal with a dichlorophenyl group, has a mean absolute oral bioavailability of approximately 96% in adults, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "A structurally related azole-containing compound was estimated to have 90% human bioavailability and was used to set safety margins, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Suvorexant, a moderately complex oral drug, has an absolute bioavailability of 82% under fasted conditions, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vilazodone has an absolute bioavailability of 72% with food, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ziprasidone has an absolute bioavailability of about 60% in the fed state, still well above the 20% threshold and supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple transferable experimental records, including structurally related azole antifungals ketoconazole, fluconazole, and voriconazole, report oral bioavailability values of 60-96%, all above the 20% threshold. No affirmative evidence supports F < 20% for the query, so the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the query molecule.",
    "Ketoconazole-like absorption can be pH- and formulation-dependent, so fasted or achlorhydric conditions might lower bioavailability.",
    "Pediatric or disease-state bioavailability can be lower than adult values, as seen with voriconazole."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

